#!/usr/bin/env node
/**
 * Extract and save Maya Chen's confirmed orders (non-cancelled)
 * from 2026-09-02 to a structured JSON file.
 */

const fs = require('fs');
const path = require('path');
const Database = require('better-sqlite3');

const DB_PATH = path.join(__dirname, '..', 'world.db');
const OUTPUT_PATH = path.join(__dirname, '..', 'data', 'maya_chen_confirmed_orders.json');

const db = new Database(DB_PATH, { readonly: true });

// 1. Find the user
const user = db.prepare(
  "SELECT user_id, name, email FROM users WHERE name = 'Maya Chen'"
).get();

if (!user) {
  console.error('User "Maya Chen" not found.');
  process.exit(1);
}

// 2. Get confirmed (non-cancelled) orders from 2026-09-02
const orders = db.prepare(`
  SELECT order_id, status, order_date, shipping_method, shipping_cost,
         tracking_number, delivery_date, payment_method, subtotal,
         discount_code, discount_amount, total_paid, is_gift
  FROM orders
  WHERE customer_id = ?
    AND status != 'cancelled'
    AND order_date = '2026-09-02'
  ORDER BY order_id
`).all(user.user_id);

// 3. For each order, fetch its line items
const getItems = db.prepare(`
  SELECT oi_id, product_id, name, quantity, unit_price, item_status
  FROM order_items
  WHERE order_id = ?
  ORDER BY oi_id
`);

const enrichedOrders = orders.map(order => ({
  ...order,
  items: getItems.all(order.order_id),
}));

// 4. Build the output document
const output = {
  extracted_at: new Date().toISOString(),
  customer: {
    user_id: user.user_id,
    name: user.name,
    email: user.email,
  },
  summary: {
    total_orders: enrichedOrders.length,
    total_amount: enrichedOrders.reduce((sum, o) => sum + o.total_paid, 0),
  },
  orders: enrichedOrders,
};

db.close();

// 5. Write to file
fs.writeFileSync(OUTPUT_PATH, JSON.stringify(output, null, 2) + '\n');
console.log(`✅ Saved ${enrichedOrders.length} confirmed orders to ${OUTPUT_PATH}`);
console.log(`   Total amount: $${output.summary.total_amount}`);

